import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import org.owasp.esapi.util.CollectionsUtil;

public class PercentCodec extends Codec {

    private static final String ALPHA_NUMERIC_STR =
            "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final String RFC3986_NON_ALPHANUMERIC_UNRESERVED_STR = "-._~";
    private static final boolean ENCODED_NON_ALPHA_NUMERIC_UNRESERVED = true;
    private static final String UNENCODED_STR = ALPHA_NUMERIC_STR
            + (ENCODED_NON_ALPHA_NUMERIC_UNRESERVED ? "" : RFC3986_NON_ALPHANUMERIC_UNRESERVED_STR);
    private static final Set<Character> UNENCODED_SET =
            CollectionsUtil.strToUnmodifiableSet(UNENCODED_STR);

    /* --------------------------------------------------------------------- */
    /*  Public API                                                             */
    /* --------------------------------------------------------------------- */

    /**
     * Encode a character for URLs.
     *
     * @param immune an optional array of characters that should not be encoded
     * @param c      the character to encode
     * @return the percent‑encoded representation of {@code c}
     * @throws IllegalArgumentException if {@code c} is {@code null}
     */
    public String encodeCharacter(char[] immune, Character c) {
        if (c == null) {
            throw new IllegalArgumentException("Character to encode must not be null");
        }

        // If the character is explicitly marked as immune, return it unchanged
        if (immune != null && contains(immune, c)) {
            return c.toString();
        }

        // Characters that are safe according to RFC 3986 are returned unchanged
        if (UNENCODED_SET.contains(c)) {
            return c.toString();
        }

        // Convert the character to UTF‑8 bytes and percent‑encode each byte
        byte[] bytes = toUtf8Bytes(c.toString());
        StringBuilder sb = new StringBuilder(bytes.length * 3);
        for (byte b : bytes) {
            appendTwoUpperHex(sb, b);
        }
        return sb.toString();
    }

    /* --------------------------------------------------------------------- */
    /*  Private helpers                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Appends the two‑digit hexadecimal representation of {@code b} to {@code sb},
     * prefixed with a '%' character. The hex digits are always upper‑case.
     *
     * @param sb the StringBuilder to append to
     * @param b  the byte to encode
     * @return the same StringBuilder instance for chaining
     */
    private static StringBuilder appendTwoUpperHex(StringBuilder sb, int b) {
        final char[] HEX_DIGITS = "0123456789ABCDEF".toCharArray();
        int unsignedByte = b & 0xFF;
        sb.append('%')
          .append(HEX_DIGITS[unsignedByte >>> 4])
          .append(HEX_DIGITS[unsignedByte & 0x0F]);
        return sb;
    }

    /**
     * Converts a string into its UTF‑8 byte representation.
     *
     * @param str the string to convert
     * @return a byte array containing the UTF‑8 encoding of {@code str}
     */
    private static byte[] toUtf8Bytes(String str) {
        // StandardCharsets.UTF_8 is available since Java 7
        return str.getBytes(StandardCharsets.UTF_8);
    }

    /**
     * Checks whether a character array contains a specific character.
     *
     * @param array the array to search
     * @param ch    the character to find
     * @return {@code true} if {@code ch} is present in {@code array}
     */
    private static boolean contains(char[] array, Character ch) {
        for (char c : array) {
            if (c == ch) {
                return true;
            }
        }
        return false;
    }

    // other methods
}
