import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * A thread‑safe, XXE‑protected Atom provider.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared, immutable Abdera engine instance. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Flag to enable/disable automatic charset detection. */
    private boolean autodetectCharset;

    /* --------------------------------------------------------------------- */
    /* MessageBodyReader implementation                                         */
    /* --------------------------------------------------------------------- */

    /**
     * Parses an Atom document from the supplied {@link InputStream} while
     * explicitly disabling XML entity resolution to mitigate XXE attacks.
     *
     * @param clazz   the expected element type
     * @param t       the generic type
     * @param a       annotations
     * @param mt      media type
     * @param headers HTTP headers
     * @param is      input stream containing the Atom XML
     * @return the root element of the parsed document
     * @throws IOException if an I/O error occurs during parsing
     */
    @Override
    public T readFrom(Class<T> clazz,
                      Type t,
                      Annotation[] a,
                      MediaType mt,
                      MultivaluedMap<String, String> headers,
                      InputStream is) throws IOException {

        if (is == null) {
            throw new IllegalArgumentException("InputStream cannot be null");
        }

        // Obtain a fresh parser instance for each call to avoid shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Create a new ParserOptions instance so that changes are isolated to this call.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        options.setResolveEntities(false);          // Disable external entity resolution
        options.setAllowDoctype(false);             // Prevent DOCTYPE declarations (if supported)

        // Parse using the secure options.
        Document<T> doc = parser.parse(is, options);

        return doc.getRoot();
    }

    /* --------------------------------------------------------------------- */
    /* Other methods omitted for brevity                                       */
    /* --------------------------------------------------------------------- */
}
