import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by normalizing the supplied
     * name and ensuring that the resulting file resides within {@code dir}.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain query parameters)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code dir} or {@code name} is null,
     *                                  empty, or would resolve outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject empty names
        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be empty");
        }

        // Normalise the path to guard against traversal
        Path normalized = Paths.get(name).normalize();

        // Reject absolute paths or paths that escape the base directory
        if (normalized.isAbsolute()
                || normalized.toString().contains("..")
                || !normalized.startsWith(".")) {
            throw new IllegalArgumentException("Invalid file name: " + name);
        }

        // Build the candidate file
        File file = new File(dir, normalized.toString());

        try {
            // Resolve canonical paths to perform a strict containment check
            File canonicalDir = dir.getCanonicalFile();
            File canonicalFile = file.getCanonicalFile();

            String dirPath = canonicalDir.getPath();
            String filePath = canonicalFile.getPath();

            if (!filePath.startsWith(dirPath + File.separator)) {
                throw new SecurityException(
                        "Attempt to create file outside the allowed directory");
            }
        } catch (IOException e) {
            // Wrap checked exception into unchecked for callers that expect none
            throw new RuntimeException("Failed to resolve canonical paths", e);
        }

        // Ensure unique filename by appending a numeric suffix if necessary
        String originalName = normalized.toString();
        int dot = originalName.indexOf('.');
        String prefix = dot < 0 ? originalName : originalName.substring(0, dot);
        String suffix = dot < 0 ? "" : originalName.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create parent directories if needed
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods

}
