                        "Resource [" + url + "] resolves to a location outside the context root");
            }

            // Convert back to a string with forward slashes for consistency
            url = normalizedPath.toString().replace(File.separatorChar, '/');

            // ---- Optional filesystem check (only if the resource maps to a physical file) ----
            String realPath = request.getServletContext().getRealPath(url);
            if (realPath != null) {
                File file = new File(realPath);
                String canonicalPath = file.getCanonicalPath();
                String rootPath = new File(request.getServletContext().getRealPath("/")).getCanonicalPath();

                if (!canonicalPath.startsWith(rootPath)) {
                    throw new ServletException(
                            "Resource [" + url + "] resolves outside the application root");
                }
