public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    // Regular expression that matches valid ISO‑639 language codes optionally followed by
    // an underscore or hyphen and a two‑letter ISO‑3166 country code.
    // Examples: "en", "en_US", "fr-FR", "de-DE"
    private static final Pattern VALID_LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2}([_-][a-zA-Z]{2})?$");

