    /**
     * Creates a Locale object from the request param, which might
     * be already a Locale or a String. The method validates the
     * string representation against a strict whitelist to prevent
     * XSS or malformed locale injection.
     *
     * @param requestedLocale the parameter from the request
     * @return the Locale or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        Locale locale = null;

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();

            if (isValidLocaleString(localeStr)) {
                // Safe to delegate to the framework's parser
                locale = LocalizedTextUtil.localeFromString(localeStr, null);
            } else {
                LOG.warn("Received invalid locale format: '{}'. Ignoring request.", localeStr);
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

    /**
     * Validates that the supplied locale string conforms to the
     * expected pattern. This prevents arbitrary strings from being
     * interpreted as locale identifiers, mitigating XSS risks.
     *
     * @param localeStr the locale string to validate
     * @return {@code true} if the string matches the pattern, {@code false} otherwise
     */
    private static boolean isValidLocaleString(String localeStr) {
        if (localeStr == null || localeStr.isEmpty()) {
            return false;
        }
        Matcher matcher = VALID_LOCALE_PATTERN.matcher(localeStr);
        return matcher.matches();
    }

