import org.apache.felix.scr.annotations.Service;
import org.apache.sling.xss.XSSAPI;

@Component
@Service(value = XSSAPI.class)
public class XSSAPIImpl implements XSSAPI {

    private SAXParserFactory factory;

    // other methods

    @Activate
    @SuppressWarnings("unused")
    protected void activate() {
        // Use the injected factory if available, otherwise create a new one
        if (factory == null) {
            factory = SAXParserFactory.newInstance();
        }

        // Disable validation and enable namespace awareness
        factory.setValidating(false);
        factory.setNamespaceAware(true);

        // Configure the factory to be XXE‑safe
        try {
            // Disallow DOCTYPE declarations entirely
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Prevent loading of external DTDs and grammars
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

            // Disable external entity resolution
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (ParserConfigurationException e) {
            // If the underlying parser does not support a feature, fail fast
            throw new IllegalStateException("Failed to configure SAXParserFactory securely", e);
        }
    }

