import java.io.InputStream;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.XMLConstants;
import java.io.IOException;

/**
 * A renderer that applies XSLT transformations to XML data.
 */
public class XsltRenderer implements Renderer {

    // No shared TransformerFactory – each call creates a fresh, securely configured instance.
    // This avoids thread‑safety issues and ensures that security settings are applied per request.

    // other methods

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     *
     * <p>The method enforces secure processing by configuring the {@link TransformerFactory}
     * with {@code FEATURE_SECURE_PROCESSING} and disabling external resource access.
     * It also guarantees that the input stream is closed after use, even when an exception
     * occurs.</p>
     *
     * @param templateStream the XSLT template as an {@link InputStream}
     * @return a configured {@link Transformer}
     * @throws IOException if the stream cannot be read or closed
     */
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        // Create a brand‑new factory for each invocation to avoid leaking configuration
        // between calls and to guarantee thread safety.
        TransformerFactory factory = TransformerFactory.newInstance();

        // Enable secure processing to prevent XXE and other XML-based attacks.
        try {
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (IllegalArgumentException | UnsupportedOperationException e) {
            // If the underlying implementation does not support the feature,
            // log a warning and continue – the factory will still be used
            // but without the explicit secure flag.
            // In production, replace System.err with a proper logging framework.
            System.err.println("Secure processing feature not supported: " + e.getMessage());
        }

        // Explicitly deny external DTD and stylesheet access to eliminate
        // the possibility of loading arbitrary resources.
        try {
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
        } catch (IllegalArgumentException e) {
            // Some implementations ignore these attributes; ignore if unsupported.
            System.err.println("External access attributes not supported: " + e.getMessage());
        }

        try {
            // Build the transformer from the provided template.
            return factory.newTransformer(new StreamSource(templateStream));
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            // Ensure the stream is always closed to avoid resource leaks.
            try {
                templateStream.close();
            } catch (IOException closeEx) {
                // Log and rethrow to surface the original failure context.
                System.err.println("Failed to close template stream: " + closeEx.getMessage());
                throw closeEx;
            }
        }
    }

    // other methods

}
