    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the target directory once to its real (canonical) path
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Reject null or empty entry names
            String entryName = nextEntry.getName();
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has no name");
            }

            // Reject absolute paths and paths that start with a separator
            Path entryPath = Paths.get(entryName);
            if (entryPath.isAbsolute() || entryName.startsWith("/") || entryName.startsWith("\\")) {
                throw new IOException("absolute or rooted entry name not allowed: " + entryName);
            }

            // Resolve and normalize the entry path against the target directory
            Path resolvedPath = targetDirPath.resolve(entryPath).normalize();

            // Ensure the resolved path is still under the target directory
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            // Convert to File for compatibility with existing API
            File f = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist
                Path parentPath = resolvedPath.getParent();
                if (parentPath != null) {
                    Files.createDirectories(parentPath);
                }

                // Write the file contents
                try (OutputStream out = Files.newOutputStream(resolvedPath, StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

