import org.apache.camel.support.ServiceSupport;

/**
 * A thread‑safe, XXE‑secure implementation of {@code XPathBuilder}.
 *
 * <p>The original implementation exposed the application to XML External Entity (XXE)
 * attacks by allowing arbitrary {@link InputSource} objects to be created from
 * untrusted strings or streams.  This patch replaces those unsafe conversions
 * with a dedicated, secure XML parser that disables all external entity
 * resolution and DTD loading.</p>
 */
public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    /* --------------------------------------------------------------------- */
    /* Secure XML parsing utilities                                         */
    /* --------------------------------------------------------------------- */

    /** Singleton factory configured to prevent XXE. */
    private static final DocumentBuilderFactory SECURE_FACTORY = createSecureFactory();

    /**
     * Creates a {@link DocumentBuilderFactory} that is hardened against XXE.
     *
     * @return a factory instance with secure defaults
     */
    private static DocumentBuilderFactory createSecureFactory() {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);
        try {
            // Disable DTDs entirely
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Disable external entities
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            // Enable secure processing
            factory.setFeature(javax.xml.XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (ParserConfigurationException e) {
            // This should never happen – if it does, the factory is unusable
            throw new IllegalStateException("Failed to configure secure XML parser", e);
        }
        return factory;
    }

    /**
     * Parses the supplied {@link InputSource} into a {@link Document} using the
     * secure factory.  Any parsing errors are propagated as {@link Exception}s.
     *
     * @param source the input source to parse
     * @return a parsed {@link Document}
     * @throws ParserConfigurationException if the parser cannot be configured
     * @throws SAXException                 if a parsing error occurs
     * @throws IOException                  if an I/O error occurs
     */
    private static Document parseSecurely(InputSource source)
            throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilder builder = SECURE_FACTORY.newDocumentBuilder();
        return builder.parse(source);
    }

    /* --------------------------------------------------------------------- */
    /* Core logic                                                             */
    /* --------------------------------------------------------------------- */

    @Override
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception conversionCause = null;

        // First attempt Camel's type conversion if a target type is defined
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                conversionCause = e;
            }
        }

        // If conversion failed or was not applicable, handle known body types
        if (answer == null) {
            if (body instanceof WrappedFile) {
                try (InputStream is = exchange.getContext()
                        .getTypeConverter()
                        .convertTo(InputStream.class, exchange, body)) {
                    answer = parseSecurely(new InputSource(is));
                }
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext()
                        .getTypeConverter()
                        .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                answer = parseSecurely(new InputSource(new StringReader((String) body)));
            }
        }

        // Fallback: if no specific type and no answer, return the original body
        if (type == null && answer == null) {
            return body;
        }

        // If we still have no answer, propagate the conversion exception or a generic one
        if (answer == null) {
            if (conversionCause != null) {
                throw conversionCause;
            }
            throw new NoTypeConversionAvailableException(body, type);
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods omitted for brevity
}
