@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    /* Feature URIs used to hard‑enforce XXE protection */
    private static final String FEATURE_EXTERNAL_GENERAL_ENTITIES   = "http://xml.org/sax/features/external-general-entities";
    private static final String FEATURE_EXTERNAL_PARAMETER_ENTITIES = "http://xml.org/sax/features/external-parameter-entities";
    private static final String FEATURE_DISALLOW_DOCTYPE_DECL       = "http://apache.org/xml/features/disallow-doctype-decl";
    private static final String FEATURE_LOAD_EXTERNAL_DTD           = "http://apache.org/xml/features/nonvalidating/load-external-dtd";
    private static final String FEATURE_LOAD_DTD_GRAMMAR            = "http://apache.org/xml/features/nonvalidating/load-dtd-grammar";

    // -------------------------------------------------------------------------

    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else {
            inputSource = new InputSource(source.getInputStream());
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        XMLReader xmlReader = null;
        SAXParserFactory sfactory = null;

        try {
            /* Prefer a pre‑configured factory from Camel if available */
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            /* Enable the standard secure‑processing feature */
            enableFeature(sfactory, XMLConstants.FEATURE_SECURE_PROCESSING, true);

            /* Disable all forms of external entity resolution */
            enableFeature(sfactory, FEATURE_LOAD_EXTERNAL_DTD, false);
            enableFeature(sfactory, FEATURE_LOAD_DTD_GRAMMAR, false);
            enableFeature(sfactory, FEATURE_EXTERNAL_GENERAL_ENTITIES, false);
            enableFeature(sfactory, FEATURE_EXTERNAL_PARAMETER_ENTITIES, false);

            /* Disallow DOCTYPE declarations entirely */
            enableFeature(sfactory, FEATURE_DISALLOW_DOCTYPE_DECL, true);

            /* Common parser configuration */
            sfactory.setNamespaceAware(true);
            sfactory.setValidating(false);
            sfactory.setXIncludeAware(false);

            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            /* Re‑apply entity‑related features on the XMLReader itself */
            enableFeature(xmlReader, FEATURE_EXTERNAL_GENERAL_ENTITIES, false);
            enableFeature(xmlReader, FEATURE_EXTERNAL_PARAMETER_ENTITIES, false);
            enableFeature(xmlReader, FEATURE_DISALLOW_DOCTYPE_DECL, true);

        } catch (ParserConfigurationException | SAXException e) {
            LOG.warn("Failed to create a secure SAXParser/XMLReader: {}", e.toString(), e);
            throw new SAXException("Unable to instantiate a secure XML reader", e);
        }

        return new SAXSource(xmlReader, inputSource);
    }

    /* --------------------------------------------------------------------- */

    /**
     * Helper to enable or disable a feature on a {@link SAXParserFactory} or {@link XMLReader}.
     * Logs a warning if the feature is unsupported but otherwise continues.
     */
    private static void enableFeature(Object target, String feature, boolean value) {
        try {
            if (target instanceof SAXParserFactory) {
                ((SAXParserFactory) target).setFeature(feature, value);
            } else if (target instanceof XMLReader) {
                ((XMLReader) target).setFeature(feature, value);
            }
        } catch (SAXException e) {
            LOG.warn("Feature {} cannot be set to {}: {}", feature, value, e.toString());
        }
    }

    // other methods
}
