 *
 * <p>In a production environment this class must enforce that the user making the request
 * is actually the owner of the account being modified.  It also performs defensive
 * checks against null values and ensures that email changes are only accepted
 * after proper verification.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is permitted to modify the SCIM user identified
     * by the path variable.  The method enforces that the authenticated user ID matches
     * the target user ID and that all mutable attributes are validated.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the update is allowed, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Verify that the request contains an authenticated user ID.
        //    In a real application this would be set by an authentication filter.
        Object authObj = request.getAttribute("authenticatedUserId");
        if (!(authObj instanceof String)) {
            return false; // No authenticated user information available
        }
        String authenticatedUserId = (String) authObj;

        // 2. Extract the target user ID from the URL path.
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // 3. Ensure the authenticated user is modifying their own record.
        if (!Objects.equals(authenticatedUserId, id)) {
            return false; // User attempting to modify another account
        }

        // 4. Read and parse the request body into a ScimUser object.
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Malformed JSON or missing fields – reject the request
            return false;
        }

        // 5. Retrieve the existing user from the database.
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow creation (handled elsewhere)
            return true;
        }

        // 6. Perform field‑by‑field validation using Objects.equals to guard against NPEs.
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            // Email change detected – require verification before allowing the change.
            // TODO: Trigger email verification workflow here.
            return false;
        }

        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
